prebuilt_msteams:
{
  "@type": "MessageCard",
  "@context": "http://schema.org/extensions",
  "themeColor": "D63638",
  "summary": "Alert: {alert_name}",
  "sections": [
    {
      "activityTitle": "🚨 Alert: {alert_name}",
      "activitySubtitle": "OpenObserve Alert Notification",
      "activityImage": "https://openobserve.ai/favicon.ico",
      "facts": [
        {
          "name": "Stream",
          "value": "{stream_name}"
        },
        {
          "name": "Type",
          "value": "{stream_type}"
        },
        {
          "name": "Status",
          "value": "🔴 Firing"
        },
        {
          "name": "Count",
          "value": "{alert_count}"
        },
        {
          "name": "Threshold",
          "value": "{alert_operator} {alert_threshold}"
        },
        {
          "name": "Time",
          "value": "{alert_time}"
        }
      ],
      "markdown": true
    }
  ],
  "potentialActions": [
    {
      "@type": "OpenUri",
      "name": "View in OpenObserve",
      "targets": [
        {
          "os": "default",
          "uri": "{alert_url}"
        }
      ]
    }
  ]
}

